    /** @description RAW blob of override, as stored — the sparse patch that the resolver interprets on read. EDITORIAL fields only. Translatable ones (title/description/tags) are a MAP by language (`{"pt-BR":…}`), with `null` in a language = "set empty". Neutral ones (original_title/release_date/ extension_data) are the scalar/object directly; `local_rating` (local rating of the owner) is a NUMBER 0–10 or `null`. Absent keys = inherited. `{}` when there is no override. Free shape (additionalProperties): the semantics per field belong to the resolver, not to the schema. */
    OverrideBlob: {
      [key: string]: unknown
    }
    /**
     * @description Sparse patch of PATCH /override. Each key is an editorial field; only the keys present are touched (sparse merge). The FORM of the VALUE depends on the field: scalars (title/original_title/description/ release_date) accept `string` or `null`; `tags` accepts an array of strings (replacement), an object `{add?:[],remove?:[]}` (merge of operations) or `null`; `extension_data` accepts an object or `null`; `local_rating` (local rating) accepts a number 0–10 or `null`; `credits` (cast/crew/production companies) accepts `null` (it deletes ALL the credits) or an object with the optional keys `cast`/`crew`/`companies` — an absent sub-key inherits the external base intact. Each block is `null` or an object with the optional operations `reorder`/`remove` (array of KEYS of the credit) / `edit` (map key→patch of fields) / `add` (array of new credits, each one requiring a `source_id` CHOSEN BY THE OWNER + `name`). The KEY of the credit is `source_id` for `cast`/`companies`; for `crew` it is `"<source_id>|<job>"` (the same key that the provider already uses for dedup — a member may have two roles with the same `source_id`). `character`/`job`/`department` in `edit`/`add` are NEUTRAL in this phase (they do not compose per language — the source does not bring those fields per language either). For TRANSLATABLE fields the value is the one of the `?lang=` language (the handler builds the per-language map); NEUTRAL fields (incl. `credits`) ignore the `lang`. `null` = set empty (do not confuse with CLEARING, which is the DELETE). A non-editorial key or an invalid shape → 422.
     * @example {
     *       "title": "Duna",
     *       "description": null,
     *       "tags": {
     *         "add": [
     *           "Clássico"
     *         ],
     *         "remove": [
     *           "Guerra"
     *         ]
     *       },
     *       "original_title": "Dune",
     *       "credits": {
     *         "cast": {
     *           "reorder": [
     *             "6193"
     *           ],
     *           "edit": {
     *             "6193": {
     *               "character": "Paul Atreides"
     *             }
     *           }
     *         },
     *         "crew": {
     *           "remove": [
     *             "1892|Producer"
     *           ],
     *           "add": [
     *             {
     *               "source_id": "custom-1",
     *               "name": "Fulano de Tal",
     *               "department": "Direção",
     *               "job": "Assistente de Direção"
     *             }
     *           ]
     *         }
     *       }
     *     }
     */
    OverridePatch: {
      [key: string]: unknown
    }
